package io.github.chronicle.quietbelow.client;

import com.google.gson.Gson;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.screen.TitleScreen;
import net.minecraft.client.gui.screen.multiplayer.ConnectScreen;
import net.minecraft.client.network.ServerAddress;
import net.minecraft.client.network.ServerInfo;
import net.minecraft.client.util.ScreenshotRecorder;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Opt-in real-time driver for the archived-world Heart air-cut reproduction. */
final class HeartAirCutSmoke {
    private static final String OUTPUT=System.getenv("CHRONICLE_HEART_AIRCUT_SMOKE"),ROOT=System.getenv("CHRONICLE_HEART_AIRCUT_SERVER_DIR"),ADDRESS="127.0.0.1:25575";
    private static final Pattern STATUS=Pattern.compile("AirCut status elapsed=(\\d+) living=(\\d+) complete=(true|false) removed=(\\d+) remoteOwned=(\\d+) newLocal=(\\d+) wardens=(\\d+) planned=(\\d+) checked=(\\d+) written=(\\d+) reason=([^ ]+) active=(true|false) beats=([0-9,]*) wardenAttempted=(true|false) wardenSpawned=(true|false)");
    private final Path output;private final List<String> messages=new ArrayList<>(),checks=new ArrayList<>(),statuses=new ArrayList<>();private final List<Step> steps=new ArrayList<>();private final long overall=System.nanoTime()+180_000_000_000L;
    private int index,baseline,elapsed,living,wardens,written,newLocal;private String burstReason="idle";private boolean burstActive,complete,connected,built,started,finished;private long deadline,nextStatus;
    private HeartAirCutSmoke(Path output,Path root)throws IOException{if(!Files.isDirectory(root)||output.toAbsolutePath().normalize().startsWith(root.toAbsolutePath().normalize()))throw new IllegalArgumentException("Air-cut report must be outside its staged server root");this.output=output;Files.createDirectories(output);}
    static void register(){if(OUTPUT==null)return;try{if(ROOT==null)throw new IllegalArgumentException("missing staged root");var smoke=new HeartAirCutSmoke(Path.of(OUTPUT),Path.of(ROOT));ClientReceiveMessageEvents.GAME.register((text,overlay)->{if(!overlay&&!smoke.finished)smoke.messages.add(text.getString());});ClientTickEvents.END_CLIENT_TICK.register(smoke::tick);}catch(Exception error){setupFail(error);MinecraftClient.getInstance().scheduleStop();}}
    private void tick(MinecraftClient client){if(finished)return;try{require(System.nanoTime()<overall,"air-cut overall timeout");if(!connected&&client.getOverlay()==null&&client.currentScreen instanceof TitleScreen){connected=true;ConnectScreen.connect(client.currentScreen,client,ServerAddress.parse(ADDRESS),new ServerInfo("Archived Heart air-cut",ADDRESS,ServerInfo.ServerType.OTHER),false,null);return;}if(client.player==null||client.world==null)return;require(client.getCurrentServerEntry()!=null&&ADDRESS.equals(client.getCurrentServerEntry().address),"air-cut address mismatch");if(!built){build(client);built=true;}if(index==steps.size()){finish(client,true,"archived Heart air-cut completed");return;}Step step=steps.get(index);if(!started){baseline=messages.size();deadline=System.nanoTime()+step.timeout*1_000_000L;step.start.run();started=true;}if(step.done.getAsBoolean()){checks.add(step.name);index++;started=false;}else require(System.nanoTime()<deadline,"timed out: "+step.name);}catch(Throwable error){finish(client,false,error.getClass().getSimpleName()+": "+error.getMessage());}}
    private void build(MinecraftClient client){command(client,"prepare archived fixture and load Heart chunks","quiet_below_heart_aircut_trial prepare","prepare",25_000);delay("allow player-loaded Heart chunks to settle",3_000);command(client,"air-cut owned Heart-window network","quiet_below_heart_aircut_trial cut","cut",25_000);waitFor("wait for complete zero-living air cut",()->poll(client,0,0,0,0,true),45_000);command(client,"capture air-cut journal baseline","quiet_below_heart_aircut_trial settle","settle",20_000);waitFor("wait through the real final effort",()->poll(client,1040,-1,0,0,false),90_000);screenshot(client,"heart-aircut-final-effort.png");command(client,"verify local growth and direct Warden","quiet_below_heart_aircut_trial verify","verify",20_000);}
    private boolean poll(MinecraftClient client,int targetElapsed,int targetLiving,int targetWardens,int targetWrites,boolean targetComplete){inspect();if(System.nanoTime()>=nextStatus){send(client,"quiet_below_heart_aircut_trial status");nextStatus=System.nanoTime()+2_000_000_000L;}return elapsed>=targetElapsed&&(targetElapsed==0||!burstActive)&&(targetLiving<0||(targetLiving==0?living==0:living>=targetLiving))&&wardens>=targetWardens&&written>=targetWrites&&(!targetComplete||complete);}
    private void inspect(){for(String message:messages.subList(baseline,messages.size())){Matcher match=STATUS.matcher(message);if(match.matches()&&!statuses.contains(message)){statuses.add(message);elapsed=Integer.parseInt(match.group(1));living=Integer.parseInt(match.group(2));complete=Boolean.parseBoolean(match.group(3));newLocal=Integer.parseInt(match.group(6));wardens=Integer.parseInt(match.group(7));written=Integer.parseInt(match.group(10));burstReason=match.group(11);burstActive=Boolean.parseBoolean(match.group(12));}}}
    private void command(MinecraftClient client,String name,String command,String expected,long timeout){step(name,()->send(client,command),()->received(expected),timeout);}private void waitFor(String name,BooleanSupplier done,long timeout){step(name,()->{nextStatus=0;elapsed=living=wardens=written=newLocal=-1;complete=false;statuses.clear();},done,timeout);}private void delay(String name,long millis){step(name,()->deadline=System.nanoTime()+millis*1_000_000L,()->System.nanoTime()>=deadline,millis+5_000);}private void screenshot(MinecraftClient client,String file){step("capture "+file,()->ScreenshotRecorder.saveScreenshot(output.toFile(),file,client.getFramebuffer(),1,ignored->{}),()->png(output.resolve("screenshots").resolve(file)),20_000);}private void step(String name,Runnable start,BooleanSupplier done,long timeout){steps.add(new Step(name,start,done,timeout));}
    private void send(MinecraftClient client,String command){client.player.networkHandler.sendChatCommand(command);}private boolean received(String expected){for(String message:messages.subList(baseline,messages.size())){if(message.startsWith("FAIL AirCut"))throw new IllegalStateException(message);if(message.equalsIgnoreCase("PASS AirCut "+expected))return true;}return false;}private void finish(MinecraftClient client,boolean pass,String detail){if(finished)return;finished=true;try{Files.writeString(output.resolve("heart-aircut.json"),new Gson().toJson(Map.of("result",pass?"PASS":"FAIL","detail",detail,"checks",checks,"statuses",statuses,"messages",messages,"elapsed",elapsed,"living",living,"wardens",wardens,"written",written,"newLocal",newLocal)));}catch(IOException ignored){}client.scheduleStop();}
    private static boolean png(Path file){try{if(!Files.isRegularFile(file))return false;byte[] b=Files.readAllBytes(file);int n=b.length;return n>24&&b[n-8]==73&&b[n-7]==69&&b[n-6]==78&&b[n-5]==68;}catch(IOException ignored){return false;}}private static void require(boolean yes,String detail){if(!yes)throw new IllegalStateException(detail);}private record Step(String name,Runnable start,BooleanSupplier done,long timeout){}private static void setupFail(Exception error){try{if(OUTPUT!=null){Files.createDirectories(Path.of(OUTPUT));Files.writeString(Path.of(OUTPUT).resolve("heart-aircut.json"),new Gson().toJson(Map.of("result","FAIL","detail","setup: "+error.getMessage())));}}catch(Exception ignored){}}
}
